import{_ as o,o as s,c as i,a3 as d}from"./chunks/framework.D4-ViStF.js";const h=JSON.parse('{"title":"哲学底座——宇宙观","description":"从道、阴阳、四象、五行建立传统智慧体系的基础世界观。","frontmatter":{"title":"哲学底座——宇宙观","description":"从道、阴阳、四象、五行建立传统智慧体系的基础世界观。","layout":"page","pageClass":"dao-doc-page dao-directory-page traditional-wisdom-directory","aside":false,"outline":false},"headers":[],"relativePath":"topics/traditional-wisdom/01-philosophy/index.md","filePath":"topics/traditional-wisdom/01-philosophy/index.md","lastUpdated":1787911578000}'),t={name:"topics/traditional-wisdom/01-philosophy/index.md"};function p(c,a,l,e,n,r){return s(),i("div",null,[...a[0]||(a[0]=[d('<h1 id="一、哲学底座——宇宙观" tabindex="-1">一、哲学底座——宇宙观 <a class="header-anchor" href="#一、哲学底座——宇宙观" aria-label="Permalink to &quot;一、哲学底座——宇宙观&quot;">​</a></h1><p>这一部分不把概念当作固定结论来背诵，而是从道、阴阳、四象、五行逐层建立观察世界的方法：事物如何生成、如何关联、如何变化。</p><p>四篇文章沿着同一条线展开，但各自也可以独立阅读。建议按次序进入，先确立整体，再理解关系、分化与运行。</p><div class="cosmology-grid"><a href="/topics/traditional-wisdom/01-philosophy/01-dao" class="cosmology-card"><span class="cosmology-card__index">01</span><div><h2>道论</h2><p>沿着生成、变化、关系与归复的线索，进入“道”作为万物运行根本的理解。</p><span class="cosmology-card__tag">根源 · 生成</span></div></a><a href="/topics/traditional-wisdom/01-philosophy/02-yin-yang" class="cosmology-card"><span class="cosmology-card__index">02</span><div><h2>阴阳论</h2><p>以“从哪里来、是什么、怎么用”三问，理解关系、对待与变化如何被看见。</p><span class="cosmology-card__tag">关系 · 变化</span></div></a><a href="/topics/traditional-wisdom/01-philosophy/03-four-symbols" class="cosmology-card"><span class="cosmology-card__index">03</span><div><h2>四象论</h2><p>从《周易》到天文方位，梳理太阴、太阳、少阴、少阳与四方星象的两条脉络。</p><span class="cosmology-card__tag">分化 · 方位</span></div></a><a href="/topics/traditional-wisdom/01-philosophy/04-five-elements" class="cosmology-card"><span class="cosmology-card__index">04</span><div><h2>五行论</h2><p>不把金木水火土当作五种材料，而是进入一张由生、克、制、化组成的关系网络。</p><span class="cosmology-card__tag">运动 · 网络</span></div></a></div><p>每篇均保留原典依据、版本提示与推导边界。读到符号、方位与时间系统时，可继续进入“符号系统”与“时间坐标系”。</p>',5)])])}const m=o(t,[["render",p]]);export{h as __pageData,m as default};
